ruleSearch.bookList:
+<js>
String(result).match(/<dl id="nr">[\w\W]+?dl>/gm).map(x=>{
let p=x.split('\n');
return{
a:p[2].match(/<a.+?>(.+?)</)[1],
b:p[3].match(/作者：<span>(.+?)</)[1],
c:p[3].match(/子类：<span>(.+?)</)[1],
d:p[3].match(/字数：<span>(.+?)</)[1],
e:p[5].match(/最新章节：<a.+>(.+?)</)[1],
f:p[4].match(/class="book_des">(.+?)</)[1],
g:p[1].match(/src="(.+?)"/)[1],
h:p[2].match(/href="(.+?)"/)[1]
}
});
</js>

