source.loginUrl:
function login() { }

function login_(openBrowser, checkMode) {
  var cookie_ = String(cookie.getKey('fanqienovel.com', 'sessionid')) ? String(cookie.getKey('fanqienovel.com', 'sessionid')) : (source.getLoginInfoMap() || {})['手动登录token']
  if (cookie_ && cookie_ != '' && !checkMode) {
    java.longToast('\n❌请勿重复登录，请先退出登录！')
    return false
  }
  if (openBrowser) {
    try {
      java.startBrowserAwait('https://fanqienovel.com/', '登录')
    } catch (e) {
      java.longToast(e)
    }
  }
  try {
    cookie.removeCookie('snssdk.com')
  } catch (e) { }
  var cookie_ = 'sessionid=' + (String(cookie.getKey('fanqienovel.com', 'sessionid')) ? String(cookie.getKey('fanqienovel.com', 'sessionid')) : (source.getLoginInfoMap() || {})['手动登录token'])
  let user
  try {
    user = JSON.parse(java.ajax('https://fanqienovel.com/api/user/info/v2,' + JSON.stringify({
      method: 'GET',
      headers: {
        'Cookie': cookie_
      }
    }))).data.name
  } catch (e) { java.log(e) }
  if (!cookie_ || cookie_ == 'sessionid=' || !user) {
    java.longToast('\n❌未获取到登录Token，登录失败')
    return false
  }
  java.longToast('\n✅用户【' + user + '】已登录')
  return true
}

function logToken() {
  java.log('番茄登录Token：' + String(cookie.getKey('fanqienovel.com', 'sessionid')) || (source.getLoginInfoMap() || {})['手动登录token'])
  java.longToast('\n✅登录Token已打印到日志，请妥善保管')
}

function logout() {
  cookie.removeCookie('fanqienovel.com')
  cookie.removeCookie('snssdk.com')
  if ((source.getLoginInfoMap() || {})['手动登录token']) java.longToast('\n✅请手动移除填写的Token')
  else java.longToast('\n✅退出登录成功')
}

function queryToken() {
  let token = String(source.getVariable())
  if (token.length <= 60) {
    java.longToast('\n❌请输入有效token')
  } else {
    let info = requestApiUrl('/user/test', { token })
    if (!info) return
    source.setVariable(token)
    java.longToast(`\n✅查询成功\n用户：${info.id}${info.max ? `\n日下载上限：${info.max}` : ''}\n今日已下载：${info.used}\n日下载剩余：${info.left}\n创建时间：${info.createTime}${info.ddl ? `\n到期时间：${info.ddlTime}` : ''}`)
    source.putLoginInfo(JSON.stringify(result))
  }
}

function getTempToken() {
  let pw1 = String(result['源作者'])
  if (pw1 == '') {
    return java.longToast('请输入源作者')
  }
  let pw2 = String(result['官方反馈群'])
  if (pw2 == '') {
    return java.longToast('请输入官方反馈群')
  }
  let pw3 = String(result['临时Token口令'])
  if (pw3 == '') {
    return java.longToast('请输入临时Token口令')
  }
  let info = requestApiUrl('/user/temp', { id: java.androidId(), pw1, pw2, pw3 })
  if (!info) return
  let token = info.token
  source.setVariable(token)
  java.longToast(`\n✅获取临时token成功\n用户：${info.id}\n日下载剩余：${info.left}\n创建时间：${info.createTime}\n到期时间：${info.ddlTime}`)
  source.putLoginInfo(JSON.stringify(result))
}

function showDb() {
  let data = requestApiUrl('/system/dbinfo', {})
  if (!data) return
  java.longToast('\n' + data.msg)
}

function downloadNovel() {
  let novelId = String(result['书籍ID'])
  if (!+novelId) {
    return java.longToast('\n❌请输入有效书籍ID')
  }
  let data = requestApiUrl('/novel/download', { novelId })
  if (!data) return
  let { msg } = data
  java.longToast(`\n✅${msg}`)
}

function setType(type) {
  source.put('type', type)
  java.longToast(`\n✅发现页模式已切换为：${type}\n刷新发现页后生效`)
}

function setGender(gender) {
  source.put('gender', gender)
  java.longToast(`\n✅发现页频道已切换为：${gender == '1' ? '男' : '女'}频\n刷新发现页后生效`)
}

