function setTone(index) {
  let tone = toneList[index - 1][1]
  source.put('tone', tone)
  let toneName = toneList[index - 1][0]
  java.longToast(`\n✅听书音色已切换为：${toneName}`)
}

function setSelfTone() {
  let tone = String(result['自定义听书音色'])
  if (tone == '' || isNaN(tone) || tone < 0) {
    return java.longToast('\n❌请输入有效音色编号')
  }
  source.put('tone', tone)
  source.putLoginInfo(JSON.stringify(result))
  java.longToast(`\n✅听书音色已切换为：${tone}`)
}

function queryTone() {
  let tone = String(source.get('tone')) || '0'
  let toneName = tone
  for (let i = 0; i < toneList.length; i++) {
    if (toneList[i][1] == tone) {
      toneName = toneList[i][0]
      break
    }
  }
  java.longToast(`\n✅当前听书音色：${toneName}`)
}

function switchSetting(key, tip) {
  let old = source.get(key) || '0'
  let now = old == '1' ? '0' : '1'
  source.put(key, now)
  java.longToast(`\n✅${key}已${now == '1' ? '开启' : '关闭'}${tip ? `\n${tip}` : ''}`)
}

function change_paragraph_comment_svg_color() {
  let color = String(result['段评气泡颜色'])
