ruleBookInfo.tocUrl:
@js:(function() {
  var url = String(baseUrl);
  if (url.match(/\/(\d{3})\/(\d+)\//)) return url;
  var bookMatch = url.match(/\/book\/(\d+)/);
  if (bookMatch) {
    var bookId = bookMatch[1];
    var prefix = bookId.substring(0, 3);
    return '/' + prefix + '/' + bookId + '/';
  }
  try {
    var doc = org.jsoup.Jsoup.parse(result);
    var a = doc.selectFirst('a[href*="/book/"]');
    if (a) {
      var href = String(a.attr('href'));
      var m = href.match(/\/book\/(\d+)/);
      if (m) {
        var bId = m[1];
        var p = bId.substring(0, 3);
        return '/' + p + '/' + bId + '/';
      }
    }
  } catch (e) {}
  return '';
})();

ruleSearch.bookList:
@js:(function() {
  var doc = org.jsoup.Jsoup.parse(result);
  var items = [];
  var rows = doc.select('p.sone');
  if (rows.size() === 0) return [];
  for (var i = 0; i < rows.size(); i++) {
    var row = rows.get(i);
    var a = row.selectFirst('a');
    if (!a) continue;
    var text = a.text().trim();
    var name = text.indexOf('/') !== -1 ? text.split('/')[0].trim() : text;
    var url = a.attr('href');
    var authorSpan = row.selectFirst('span.author a');
    var author = authorSpan ? authorSpan.text().trim() : '';
    items.push({
      name: name,
      url: url,
      author: author
    });
  }
  return items;
})();

